const raw = $input.first().json;

function buildMapsLink(title, address) {
  const q = encodeURIComponent([title, address].filter(Boolean).join(' '));
  return `https://www.google.com/maps/search/?api=1&query=${q}`;
}

let items = [];

if (Array.isArray(raw.organic_results) && raw.organic_results.length > 0) {
  items = raw.organic_results.slice(0, 3).map(r => ({
    title: r.title || '',
    link: r.link || ''
  })).filter(r => r.link);
}

if (items.length === 0 && raw.local_results) {
  const places = Array.isArray(raw.local_results) ? raw.local_results : (raw.local_results.places || []);
  items = places.slice(0, 3).map(p => ({
    title: p.title || '',
    link: p.website || p.link || buildMapsLink(p.title, p.address)
  }));
}

if (items.length === 0 && Array.isArray(raw.news_results)) {
  items = raw.news_results.slice(0, 3).map(n => ({
    title: n.title || '',
    link: n.link || ''
  })).filter(r => r.link);
}

const output = items.length > 0
  ? items.map((it, i) => `${i + 1}. ${it.title}\n${it.link}`).join('\n')
  : '搜尋沒有找到相關結果的來源連結。';

return [{ json: { output, resultCount: items.length } }];
